        CSVParser parser = CSVParser.parse("a;b\nc;d", CSVFormat.RFC4180);
        List<CSVRecord> records = parser.getRecords();
        assertThat(records.size(), is(2));
        assertThat(records.get(0).get(0), is("a"));
